from copy import deepcopy


class MonitorAdapter:
    def __init__(self, backend):
        self._backend = backend
        self._config = None
        self._initialized = False
        self._released = False

    def initialize(self, config):
        self._ensure_active()
        if self._initialized:
            raise RuntimeError("already initialized")
        if not isinstance(config, dict):
            raise TypeError("config must be a dictionary")
        self._backend.initialize(config)
        self._config = deepcopy(config)
        self._initialized = True

    def run(self):
        self._ensure_ready()
        return self._backend.start()

    def release(self):
        if not self._released:
            self._backend.close()
            self._released = True

    def write_log(self, level, message, category=None):
        self._ensure_ready()
        if not isinstance(level, int) or isinstance(level, bool):
            raise TypeError("level must be an integer")
        if not isinstance(message, str):
            raise TypeError("message must be a string")
        if category is not None and not isinstance(category, str):
            raise TypeError("category must be a string or None")
        encoded_category = None if category is None else category.encode("utf-8")
        return self._backend.log(level, message.encode("utf-8"), encoded_category)

    def set_position(self, symbol, quantity):
        self._ensure_ready()
        if not isinstance(symbol, str):
            raise TypeError("symbol must be a string")
        if not symbol.strip():
            raise ValueError("symbol must be nonempty")
        if not isinstance(quantity, int) or isinstance(quantity, bool):
            raise TypeError("quantity must be an integer")
        return self._backend.target(symbol.encode("utf-8"), quantity)

    def config_snapshot(self):
        return deepcopy(self._config)

    def _ensure_active(self):
        if self._released:
            raise RuntimeError("adapter has been released")

    def _ensure_ready(self):
        self._ensure_active()
        if not self._initialized:
            raise RuntimeError("adapter is not initialized")

